parameters.jsCode:
// Nodo 3 — Parseo del XML de Nmap.
// Manejo de errores real: try/catch real, parseStringPromise
// (async, no callback), encadenamiento opcional en todo acceso a campos
// que pueden no existir (evita que un host "raro" tire abajo el nodo).
// v2: agrega los timestamps reales del escaneo (tomados del propio XML
// de Nmap, no de la hora de ejecución de n8n).

const { parseStringPromise } = require('xml2js');

const results = [];

for (const item of $input.all()) {
  const rawXml = item.json.stdout;

  if (!rawXml) {
    throw new Error('El item no contiene stdout con el XML de Nmap. Verificar el nodo "Ejecutar Escaneo Nmap" anterior.');
  }

  let parsed;
  try {
    parsed = await parseStringPromise(rawXml, { explicitArray: true });
  } catch (err) {
    results.push({
      json: {
        parseError: true,
        errorMessage: err.message,
        rawXmlSnippet: rawXml.slice(0, 200),
      },
    });
    continue;
  }

  // Timestamps reales del escaneo, tomados del propio Nmap (epoch en
  // segundos -> ISO 8601 para que Postgres los acepte sin conversión).
  const startEpoch = parsed?.nmaprun?.$?.start ?? null;
  const endEpoch = parsed?.nmaprun?.runstats?.[0]?.finished?.[0]?.$?.time ?? null;
  const scanStartedAt = startEpoch ? new Date(Number(startEpoch) * 1000).toISOString() : null;
  const scanFinishedAt = endEpoch ? new Date(Number(endEpoch) * 1000).toISOString() : null;

  const hosts = parsed?.nmaprun?.host ?? [];

  for (const host of hosts) {
    const address = host?.address?.[0]?.$?.addr ?? 'unknown';
    const hostname = host?.hostnames?.[0]?.hostname?.[0]?.$?.name ?? null;
    const hostStatus = host?.status?.[0]?.$?.state ?? 'unknown';
    const ports = host?.ports?.[0]?.port ?? [];

    if (ports.length === 0) {
      results.push({
        json: {
          parseError: false,
          hostIp: address,
          hostname,
          hostStatus,
          port: null,
          protocol: null,
          serviceName: null,
          serviceProduct: null,
          serviceVersion: null,
          scanStartedAt,
          scanFinishedAt,
        },
      });
      continue;
    }

    for (const port of ports) {
      const service = port?.service?.[0]?.$ ?? {};
      results.push({
        json: {
          parseError: false,
          hostIp: address,
          hostname,
          hostStatus,
          port: port?.$?.portid ?? null,
          protocol: port?.$?.protocol ?? null,
          portState: port?.state?.[0]?.$?.state ?? 'unknown',
          serviceName: service.name ?? null,
          serviceProduct: service.product ?? null,
          serviceVersion: service.version ?? null,
          serviceExtraInfo: service.extrainfo ?? null,
          scanStartedAt,
          scanFinishedAt,
        },
      });
    }
  }
}

return results;

// Nodo 4 — Preparar resumen para scan_history.
// Corre una sola vez sobre TODOS los items que produjo el Nodo 3 (parseo),
// y arma un único registro-resumen del escaneo completo.

const crypto = require('crypto');

const items = $input.all();

if (items.length === 0) {
  throw new Error('No hay items de entrada: el escaneo no produjo ningún resultado.');
}

// Todos los items de una misma corrida comparten los mismos timestamps de
// escaneo (vienen del mismo XML de Nmap), así que tomamos el primero.
const scanStartedAt = items[0].json.scanStartedAt;
const scanFinishedAt = items[0].json.scanFinishedAt;

// Hosts únicos detectados (por si en el futuro escaneamos un rango con
// varios hosts, no solo target1).
const uniqueHosts = new Set(items.map((i) => i.json.hostIp).filter(Boolean));

return [
  {
    json: {
      scanUuid: crypto.randomUUID(),
      targetRange: Array.from(uniqueHosts).join(', '),
      startedAt: scanStartedAt,
      finishedAt: scanFinishedAt,
      hostCount: uniqueHosts.size,
      findingCount: items.length,
    },
  },
];

parameters.query:
INSERT INTO scan_history (scan_uuid, target_range, started_at, finished_at, host_count, finding_count, status)
VALUES ($1, $2, $3, $4, $5, $6, 'running')
RETURNING id;

parameters.jsCode:
// Nodo 6 — Adjuntar el scan_id (generado en el Nodo 5 / "Insert Scan
// History") a cada hallazgo individual, antes de insertarlos en
// vulnerability_scans.
//
// El INSERT del Nodo 5 devuelve solo el id (RETURNING id), sin los campos
// de los hallazgos. Por eso el id se recupera por nombre de nodo, y los
// hallazgos se leen del Nodo 3 ("Parsear XML Nmap"). Es un mecanismo
// nativo de n8n que no depende de que los datos "viajen solos" entre
// nodos. Así el scan_id se propaga a cada item sin pérdida.

const scanId = $('Insert Scan History').first().json.id;
const findings = $('Parsear XML Nmap').all();

if (scanId === undefined || scanId === null) {
  throw new Error('No se pudo obtener el scan_id del nodo "Insert Scan History".');
}

return findings.map((item) => ({
  json: {
    ...item.json,
    scanId,
  },
}));

// Antes de arrancar la secuencia GMP, reducir a un solo item —
// mismo motivo que "Code in JavaScript" más abajo. "Insert rows in a
// table" produce UN item por cada puerto que encontró Nmap (3 en este
// laboratorio). Sin este paso, "GMP Create Target" correría una vez POR
// CADA uno de esos items, creando 3 targets/tareas/escaneos duplicados en
// GVM en vez de uno solo.
return [{ json: {} }];

// Captura explícita del target_id — mismo criterio que "Adjuntar Scan Id":
// nunca asumir que un ID "se puede arrastrar solo" entre nodos,
// capturarlo siempre a mano.
// port_list obligatorio confirmado en vivo: create_target sin port_list
// devuelve 400 "One of PORT_LIST and PORT_RANGE are required" — no estaba
// documentado antes de tener GVM instalado.
const stdout = $input.first().json.stdout ?? '';
const statusMatch = stdout.match(/<create_target_response status="(\d+)"/);
const idMatch = stdout.match(/<create_target_response[^>]*\sid="([^"]+)"/);

if (!statusMatch || statusMatch[1] !== '201' || !idMatch) {
  throw new Error(`create_target no devolvió un id válido. Salida cruda: ${stdout}`);
}

return [{ json: { targetId: idMatch[1] } }];

// config_id = "Full and fast" y scanner_id = "OpenVAS Default" son
// constantes: IDs de objetos ya existentes en esta instancia de GVM (se
// obtuvieron una sola vez con get_configs/get_scanners y se documentaron
// en gvm-integration/hallazgo-estructura-real-get-reports.md), no algo
// que haga falta recrear en cada corrida — por eso van hardcodeados en el
// nodo anterior en vez de resolverse acá.
const stdout = $input.first().json.stdout ?? '';
const statusMatch = stdout.match(/<create_task_response status="(\d+)"/);
const idMatch = stdout.match(/<create_task_response[^>]*\sid="([^"]+)"/);

if (!statusMatch || statusMatch[1] !== '201' || !idMatch) {
  throw new Error(`create_task no devolvió un id válido. Salida cruda: ${stdout}`);
}

return [{ json: { taskId: idMatch[1] } }];

// Guarda taskId (del nodo "GMP Parsear Task Id") y reportId (recién
// obtenido) juntos: el loop de espera que sigue necesita ambos. Los nodos
// de tipo Execute Command no propagan los campos del item de entrada (solo
// emiten stdout/stderr/exitCode). Por eso cada nodo del loop los vuelve a
// pedir por nombre de nodo, en vez de esperar que "viajen solos", con el
// mismo criterio que en el resto del workflow.
const stdout = $input.first().json.stdout ?? '';
const statusMatch = stdout.match(/<start_task_response status="(\d+)"/);
const reportIdMatch = stdout.match(/<report_id>([^<]+)<\/report_id>/);

if (!statusMatch || statusMatch[1] !== '202' || !reportIdMatch) {
  throw new Error(`start_task no devolvió un report_id válido. Salida cruda: ${stdout}`);
}

const taskId = $('GMP Parsear Task Id').first().json.taskId;

return [{ json: { taskId, reportId: reportIdMatch[1] } }];

// Un Wait fijo no puede anticipar la duración real de una evaluación de
// GVM, que depende de los servicios detectados y no es constante: se
// sondea get_tasks cada 15s (nodo "GMP Esperar Antes de Sondear") hasta
// ver status=Done.
//
// Límite de seguridad real, no arbitrario: durante el desarrollo
// (21/08/2026) un escaneo quedó vivo pero prácticamente sin avanzar 47
// minutos por una lista de puertos UDP mal elegida en create_target (ver
// gvm-integration/hallazgo-estructura-real-get-reports.md). $runIndex
// cuenta cuántas vueltas dio este nodo en el loop; 240 vueltas a 15s = 1
// hora antes de fallar con un error explícito, en vez de esperar para
// siempre.
const MAX_POLLS = 240;

const stdout = $input.first().json.stdout ?? '';
const statusMatch = stdout.match(/<status>([^<]+)<\/status>/);
const progressMatch = stdout.match(/<progress>(\d+)<\/progress>/);

if (!statusMatch) {
  throw new Error(`No se pudo leer <status> de get_tasks. Salida cruda: ${stdout}`);
}

const status = statusMatch[1];
const { taskId, reportId } = $('GMP Parsear Report Id').first().json;

if (['Stopped', 'Interrupted', 'Error'].includes(status)) {
  throw new Error(`La tarea GVM ${taskId} terminó en estado inesperado: ${status}. Salida cruda: ${stdout}`);
}

if ($runIndex >= MAX_POLLS) {
  throw new Error(`La tarea GVM ${taskId} no terminó después de ${MAX_POLLS} sondeos (~1 hora). Puede estar mal configurada (ver el incidente real de la lista de puertos UDP documentado en el repo). Se aborta en vez de esperar indefinidamente.`);
}

return [{
  json: {
    taskId,
    reportId,
    status,
    progress: progressMatch ? Number(progressMatch[1]) : null,
  },
}];

// Nodo de parseo GVM/GMP — VERSIÓN REAL, contra una instancia real de
// GVM/Greenbone, no contra datos simulados. Corregido contra la respuesta
// real de gvmd 26.36.1 / GVM 22.7. (ver
// gvm-integration/hallazgo-estructura-real-get-reports.md para el detalle
// completo y el XML de ejemplo real).
//
// Dos diferencias reales confirmadas contra lo que asumía el mock:
//
// 1) NO existe una etiqueta <cve> limpia dentro de <nvt>. Los CVEs vienen como
//    texto libre dentro de <tags>, en la sub-parte "insight=", y un solo
//    resultado de GVM puede mencionar VARIOS CVEs (los NVT tipo "Multiple
//    Vulnerabilities" agrupan CVEs relacionados con la misma versión de
//    software). Acá se extraen con una regex sobre el texto de "insight".
//
// 2) <host> no es un elemento de solo texto: tiene contenido mixto
//    (texto + hijos <asset/> y <hostname>). Con xml2js (explicitArray: true,
//    explicitCharkey por defecto), el texto queda bajo la clave "_", no
//    directamente en r.host[0] como asumía el mock.
//
// Decisión de diseño (22/08/2026, tras verificar el comportamiento real de GVM):
// como un mismo host:puerto puede tener MUCHOS hallazgos reales de GVM (se
// vio un caso real: 42 hallazgos distintos en el puerto 80 de target1), no
// alcanza con "actualizar" la única fila que dejó Nmap para ese puerto sin
// truncar datos. Se decidió INSERTAR una fila nueva por cada CVE encontrado,
// dejando la fila original de Nmap intacta como reconocimiento base. Menos
// prolijo que 1 fila por puerto, pero consistente con el principio del repo
// de no truncar resultados.
//
// Resultados sin ningún CVE en el texto:
//   - threat === 'Log' (ruido puramente informativo, ej. banners de detección
//     de versión sin vulnerabilidad asociada): se descartan, igual que la
//     propia UI de GVM los trata como no accionables por defecto.
//   - cualquier otro threat (Low/Medium/High/Critical) sin CVE textual (ej.
//     hallazgos de configuración sin CVE asignado): se conserva UNA fila con
//     cve_id = null — es un hallazgo real, no ruido, y el esquema ya tolera
//     cve_id nulo.

const { parseStringPromise } = require('xml2js');

// Traducción de los niveles de threat de GMP a las etiquetas en español que
// usa nuestro esquema (columna severity_label: Crítica | Alta | Media | Baja | Ninguna).
const THREAT_TO_LABEL = {
  Critical: 'Crítica',
  High: 'Alta',
  Medium: 'Media',
  Low: 'Baja',
  Log: 'Ninguna',
  Debug: 'Ninguna',
};

const CVE_REGEX = /CVE-\d{4}-\d+/g;

function extraerTag(tagsString, clave) {
  // El campo "tags" de un NVT viene como pares clave=valor separados por "|",
  // ej: "summary=...|insight=...|solution=...". Convención documentada por
  // Greenbone; no hay subelementos separados para cada una en get_reports.
  if (!tagsString) return null;
  const partes = tagsString.split('|');
  for (const parte of partes) {
    const idx = parte.indexOf('=');
    if (idx === -1) continue;
    const k = parte.slice(0, idx).trim();
    const v = parte.slice(idx + 1).trim();
    if (k === clave) return v || null;
  }
  return null;
}

function extraerHostIp(hostNode) {
  // Contenido mixto real: texto (IP) + <asset/> + <hostname>. xml2js deja el
  // texto bajo "_" cuando hay hijos. Si algún día no hubiera hijos (como
  // asumía el mock), r.host[0] sería directamente el string — se contempla
  // igual por robustez.
  if (hostNode == null) return null;
  if (typeof hostNode === 'string') return hostNode;
  return hostNode._ ?? null;
}

function extraerCves(tagsString) {
  const insight = extraerTag(tagsString, 'insight') ?? '';
  const matches = insight.match(CVE_REGEX);
  return matches ? [...new Set(matches)] : [];
}

const scanId = $('Insert Scan History').first().json.id;
if (scanId === undefined || scanId === null) {
  throw new Error('No se pudo obtener el scan_id del nodo "Insert Scan History".');
}

const results = [];

for (const item of $input.all()) {
  const rawXml = item.json.stdout;

  if (!rawXml) {
    throw new Error('El item no contiene stdout con el XML de get_reports. Verificar el nodo "GMP Get Reports" anterior.');
  }

  let parsed;
  try {
    parsed = await parseStringPromise(rawXml, { explicitArray: true });
  } catch (err) {
    throw new Error(`No se pudo parsear el XML de get_reports: ${err.message}. Fragmento: ${rawXml.slice(0, 300)}`);
  }

  const reportResults =
    parsed?.get_reports_response?.report?.[0]?.report?.[0]?.results?.[0]?.result ?? [];

  if (reportResults.length === 0) {
    // 0 hallazgos es un resultado válido (target sin vulnerabilidades
    // detectadas), no un error — no se inserta nada, se sigue el flujo.
    continue;
  }

  for (const r of reportResults) {
    const hostIp = extraerHostIp(r?.host?.[0]);
    // formato normal "80/tcp"; pero también aparece "general/tcp",
    // "general/icmp", "general/CPE-T" para hallazgos a nivel de host/SO,
    // no atados a un puerto real (ej. detección de sistema operativo).
    // Caso real (22/08/2026): Number("general") da NaN, que al
    // serializarse a JSON se convierte en null silenciosamente, y ese null
    // terminaba llegando a Postgres como el TEXTO "null" en vez de un NULL
    // real, rompiendo el INSERT en la columna entera port. Se detecta
    // explícitamente con Number.isInteger en vez de confiar en el ternario.
    const portRaw = r?.port?.[0] ?? null;
    let portNum = null;
    let protocol = null;
    if (portRaw) {
      const [portPart, protoPart] = portRaw.split('/');
      const parsedPort = Number(portPart);
      portNum = Number.isInteger(parsedPort) ? parsedPort : null;
      protocol = protoPart ?? null;
    }

    const nvt = r?.nvt?.[0] ?? {};
    const tags = nvt?.tags?.[0] ?? null;

    const threat = r?.threat?.[0] ?? 'Log';
    const severityScore = Number(r?.severity?.[0] ?? 0);
    const description = extraerTag(tags, 'summary') ?? r?.description?.[0] ?? null;
    const solution = extraerTag(tags, 'solution') ?? null;

    const baseFields = {
      hostIp,
      port: portNum,
      protocol,
      severityScore,
      severityLabel: THREAT_TO_LABEL[threat] ?? 'Ninguna',
      description,
      solution,
      scanId,
    };

    const cves = extraerCves(tags);

    if (cves.length > 0) {
      for (const cveId of cves) {
        results.push({ json: { ...baseFields, cveId } });
      }
    } else if (threat !== 'Log') {
      results.push({ json: { ...baseFields, cveId: null } });
    }
    // threat === 'Log' sin CVE: se descarta (ver comentario del encabezado).
  }
}

return results;

// Reduce a un único item antes de la consulta SELECT, para que el nodo
// Postgres siguiente ejecute la query una sola vez (no una vez por fila
// insertada).
//
// Se lee el scan_id por nombre de nodo ("Insert Scan
// History"), no de $input — así sigue funcionando aunque el nodo anterior
// ("GMP Insertar Hallazgos") produzca 0 items (puede pasar si GVM no
// encontró ningún hallazgo con CVE ni con threat distinto de Log).
return [{ json: { scanId: $('Insert Scan History').first().json.id } }];

parameters.query:
WITH count_update AS (
  UPDATE scan_history SET finding_count = (SELECT count(*) FROM vulnerability_scans WHERE scan_id = $1) WHERE id = $1
)
SELECT * FROM vulnerability_scans WHERE scan_id = $1 ORDER BY id;

parameters.jsCode:
// Nodo 25 — Generar Informe Markdown.
//
// Recorre el 100% de las filas devueltas por la consulta a PostgreSQL, sin ningún límite
// arbitrario sobre la cantidad de resultados mostrados, e incluye el inventario de hosts
// declarado en el Objetivo Específico 6.
//
// Estado actual: GVM/Greenbone real ya está integrado (ver
// docs/resultados-10-corridas-gvm.md). Los hallazgos con cve_id,
// severity_score, severity_label, description y solution poblados son
// correlaciones reales contra CVEs conocidos (no solo reconocimiento de
// Nmap) — ver gvm-integration/hallazgo-estructura-real-get-reports.md
// para el detalle completo de cómo se construyó el parseo real. El
// código de este nodo no necesitó cambios estructurales para esto, tal
// como se planeó desde el mock: solo se ajustaron los dos detalles reales
// documentados más abajo (deduplicación de puertos, y el caso de filas de
// GVM sin service_name propio).

const findings = $input.all().map((item) => item.json);
const summary = $('Resumen Scan History').first().json;

// El campo summary.finishedAt se capturaba apenas terminaba Nmap,
// antes de que arrancara GVM — reflejaba ~6s en vez de los ~14 minutos reales.
// Se sobreescribe acá con el timestamp real, tomado después de que GVM terminó e
// insertó sus hallazgos.
const finReal = $('Actualizar Fin Real Scan History').first().json?.finished_at;
if (finReal) summary.finishedAt = finReal;

if (findings.length === 0) {
  throw new Error('No se recibieron hallazgos desde la consulta a PostgreSQL. Verificar el nodo anterior.');
}

// --- Inventario de hosts, declarado en el Objetivo Específico 6 ---
//
// Caso real (24/08/2026): con GVM insertando una fila por CADA CVE
// (varias por puerto), "ports" sin deduplicar terminaba listando el mismo
// puerto decenas de veces (ej. "80" repetido 70 veces).
// Se usa un Set para que cada puerto aparezca una sola
// vez, sin perder la cuenta real de hallazgos (que sí cuenta cada fila).
const hostMap = new Map();
for (const f of findings) {
  if (!hostMap.has(f.host_ip)) {
    hostMap.set(f.host_ip, { hostname: f.hostname, count: 0, ports: new Set() });
  }
  const entry = hostMap.get(f.host_ip);
  entry.count += 1;
  if (f.port != null) entry.ports.add(f.port);
}

let hostInventory = '| Host (IP) | Hostname | Puertos detectados | Cant. hallazgos |\n';
hostInventory += '|---|---|---|---|\n';
for (const [ip, data] of hostMap.entries()) {
  hostInventory += `| ${ip} | ${data.hostname ?? 'N/D'} | ${[...data.ports].sort((a, b) => a - b).join(', ')} | ${data.count} |\n`;
}

// --- Agrupación por severidad (si GVM ya la completó) o por servicio
// (mientras tanto, con datos de reconocimiento de Nmap) ---
const hasSeverityData = findings.some((f) => f.severity_label);

let detailSection = '';
if (hasSeverityData) {
  // Etiquetas en español, consistentes con la columna severity_label del
  // esquema (sql/init/01_schema.sql: "Crítica | Alta | Media | Baja | Ninguna").
  // Con etiquetas en inglés (Critical/High/Medium/Low), ningún hallazgo
  // coincidiría con los valores persistidos de severity_label, y no se
  // agruparía por severidad sin ningún error visible que lo advirtiera.
  const bySeverity = { Crítica: [], Alta: [], Media: [], Baja: [], Ninguna: [] };
  for (const f of findings) {
    const label = f.severity_label ?? 'Ninguna';
    (bySeverity[label] ?? bySeverity.Ninguna).push(f);
  }
  for (const [label, items] of Object.entries(bySeverity)) {
    if (items.length === 0) continue;
    detailSection += `\n### ${label} (${items.length})\n\n`;
    for (const f of items) {
      // Las filas que vienen de GVM no tienen service_name/
      // service_version propio (solo lo captura Nmap) — se omite el
      // paréntesis en vez de mostrar el feo "— null (null)".
      const servicio = f.service_name
        ? ` — ${f.service_name}${f.service_version ? ` (${f.service_version})` : ''}`
        : '';
      const portLabel = f.port != null ? f.port : 'general';
      detailSection += `- **${f.host_ip}:${portLabel}/${f.protocol}**${servicio}\n`;
      if (f.cve_id) detailSection += `  - CVE: ${f.cve_id}\n`;
      if (f.description) detailSection += `  - Descripción: ${f.description}\n`;
      if (f.solution) detailSection += `  - Solución recomendada: ${f.solution}\n`;
    }
  }
} else {
  detailSection += `\n### Hallazgos de reconocimiento (Nmap) — pendientes de correlación con GVM\n\n`;
  detailSection += `> Estos ${findings.length} hallazgos provienen de la detección de servicios y versiones de Nmap. `;
  detailSection += `Todavía no fueron correlacionados contra una base de datos de CVE (GVM/Greenbone). `;
  detailSection += `No deben interpretarse como vulnerabilidades confirmadas.\n\n`;
  for (const f of findings) {
    detailSection += `- **${f.host_ip}:${f.port}/${f.protocol}** — ${f.service_name}: ${f.service_version}\n`;
  }
}

// --- Recomendaciones generales de remediación ---
const recommendations = [
  'Priorizar la remediación de los hallazgos de severidad Crítica y Alta con CVE conocido, confirmados por correlación real contra GVM/Greenbone.',
  'Mantener actualizado el software de cada servicio detectado a su versión estable más reciente.',
  'Restringir el acceso de red a los puertos detectados únicamente a los hosts que efectivamente lo necesiten.',
  'Repetir este escaneo de forma periódica para detectar desviaciones respecto de esta línea base.',
];

const report = `# Informe de Escaneo de Red

**ID de escaneo:** ${summary.scanUuid}
**Rango/objetivo:** ${summary.targetRange}
**Inicio:** ${summary.startedAt}
**Fin:** ${summary.finishedAt}
**Hosts analizados:** ${summary.hostCount}
**Hallazgos totales:** ${findings.length} recuperados de la base de datos

## Inventario de hosts

${hostInventory}

## Detalle de hallazgos
${detailSection}

## Recomendaciones generales

${recommendations.map((r) => `- ${r}`).join('\n')}

---
*Informe generado automáticamente. Fuente de datos: tabla \`vulnerability_scans\`, scan_id = ${findings[0].scan_id}.*
`;

return [{ json: { reportMarkdown: report, findingCount: findings.length } }];
